# ruff: noqa: E501
"""Whole bounded drift rows with full-universe totals and immutable planning context."""

from .read_widget import read_widget

DRIFT_WIDGET_URI = "ui://trading212-portfolio/drift-v1.html"
DRIFT_WIDGET_MIME = "text/html;profile=mcp-app"
_SCRIPT = r"""
function parseInput(a){if(!record(a)||!Object.keys(a).every(k=>["account_id","snapshot_id","virtual_portfolio_id","target_version_id","reporting_currency","basis","xray_run_id","top_n"].includes(k)))return null;const p={};for(const k of ["account_id","snapshot_id","virtual_portfolio_id","target_version_id"]){p[k]=inputUUID(a[k]);if(!p[k])return null;}p.reporting_currency=a.reporting_currency;p.basis=a.basis??"direct";p.top_n=a.top_n??25;p.xray_run_id=a.xray_run_id??null;if(p.xray_run_id!==null){p.xray_run_id=inputUUID(p.xray_run_id);if(!p.xray_run_id)return null;}return currency(p.reporting_currency)&&["direct","effective"].includes(p.basis)&&count(p.top_n,50)&&p.top_n>0?p:null;}
function rowOK(x,c){return record(x)&&str(x.key,120)&&str(x.name,160)&&["group","holding","cash","unclassified"].includes(x.kind)&&decimal(x.target_weight)&&["actual_value","monetary_gap"].every(k=>x[k]===null||money(x[k])&&x[k].currency===c)&&["actual_direct_weight","effective_weight","signed_drift","absolute_drift","relative_drift"].every(k=>x[k]===null||decimal(x[k]))&&(quality(x.quality)||x.quality==="unavailable")&&str(x.effective_weight_reason,120)&&(x.relative_drift_reason===null||str(x.relative_drift_reason,120))&&(x.classification===null||["underweight","on_target","overweight"].includes(x.classification));}
function validateResult(e,p){const d=e?.data,c=d?.context,t=d?.totals;if(!record(e)||e.error!==null||e.execution_allowed!==false||!record(d)||!record(c)||!record(t))return false;if(!["account_id","snapshot_id","virtual_portfolio_id","target_version_id","reporting_currency"].every(k=>c[k]===p[k])||d.basis!==p.basis||d.top_n!==p.top_n)return false;
 if(p.xray_run_id!==null&&d.company_basis?.xray_run_id!==p.xray_run_id)return false;if(p.xray_run_id===null&&(d.company_basis??null)!==null)return false;
 return ["as_of","source_cutoff_at","calculated_at"].every(k=>instant(c[k]))&&digest(c.input_digest)&&digest(d.content_digest)&&record(c.method)&&str(c.method.name,80)&&str(c.method.version,120)&&record(c.data_quality)&&(quality(c.data_quality.state)||c.data_quality.state==="unavailable")&&array(c.sources,8192,s=>record(s)&&str(s.kind,120)&&uuid(s.id)&&digest(s.content_digest)&&str(s.version,120)&&instant(s.effective_at)&&instant(s.first_observed_at))&&array(c.warnings,1280,w=>record(w)&&str(w.code,120)&&str(w.message))&&array(c.assumptions,256,w=>record(w)&&str(w.code,120)&&str(w.message))&&record(c.coverage)&&typeof c.coverage.complete==="boolean"&&["valued_total","matched_total","unclassified_total"].every(k=>money(c.coverage[k]))&&(c.coverage.denominator===null||money(c.coverage.denominator))&&["matched_weight","unclassified_weight","unresolved_target_weight"].every(k=>c.coverage[k]===null||decimal(c.coverage[k]))&&["value","cash","unclassified"].every(k=>t[k]===null||money(t[k])&&t[k].currency===p.reporting_currency)&&["l1_drift","weighted_squared_drift","effective_weight_rounding_residual"].every(k=>t[k]===null||decimal(t[k]))&&["groups","leaves","cash_and_unclassified"].every(k=>array(d[k],50,x=>rowOK(x,p.reporting_currency)))&&count(d.eligible_rows,4353)&&count(d.omitted_rows,4353)&&d.groups.length+d.leaves.length+d.cash_and_unclassified.length+d.omitted_rows===d.eligible_rows;}
function toolName(){return "get_drift_analysis";}
function toolArguments(p){return {...p};}
function nextArguments(){return null;}
function renderData(e,parent){const d=e.data,c=d.context,t=d.totals;para(parent,`Account ${c.account_id}; snapshot ${c.snapshot_id}; target ${c.target_version_id}; ${d.basis} basis. ${d.eligible_rows-d.omitted_rows} of ${d.eligible_rows} ranked rows shown; ${d.omitted_rows} omitted. Totals cover the full universe, not just this sample. Ratios remain exact: 0.01 means 1%.`);para(parent,`Method ${c.method.name} ${c.method.version}; quality ${c.data_quality.state}; availability ${c.availability}; reason ${c.reason_code??"None"}. Valuation ${c.as_of}; cutoff ${c.source_cutoff_at}; calculated ${c.calculated_at}.`);
 table(parent,"Full-universe drift totals",["Measure","Exact value"],[["Portfolio value",moneyText(t.value)],["Cash",moneyText(t.cash)],["Unclassified",moneyText(t.unclassified)],["L1 drift",exact(t.l1_drift)],["Weighted squared drift",exact(t.weighted_squared_drift)],["Effective weight rounding residual",exact(t.effective_weight_rounding_residual)]]);
 for(const [key,label] of [["groups","Groups"],["leaves","Holdings"],["cash_and_unclassified","Cash and unclassified"]])table(parent,label,["Row / quality","Actual / gap","Target / actual weight","Signed / absolute / relative drift"],d[key].map(x=>[`${x.name}; ${x.kind}; ${x.quality}`,`${moneyText(x.actual_value)} / ${moneyText(x.monetary_gap)}`,`${x.target_weight} / ${exact(x.actual_direct_weight)}; effective ${exact(x.effective_weight)} (${x.effective_weight_reason})`,`${exact(x.signed_drift)} / ${exact(x.absolute_drift)} / ${exact(x.relative_drift)}; ${x.relative_drift_reason??x.classification??"Unavailable"}`]));
 const proof=disclosure(parent,"Immutable source and quality proof");const v=c.coverage;para(proof,`Coverage complete ${v.complete}; denominator ${moneyText(v.denominator)}; valued ${moneyText(v.valued_total)}; matched ${moneyText(v.matched_total)}; unclassified ${moneyText(v.unclassified_total)}; matched weight ${exact(v.matched_weight)}; unclassified weight ${exact(v.unclassified_weight)}; unresolved target weight ${exact(v.unresolved_target_weight)}.`);para(proof,`Input ${c.input_digest}; result ${d.content_digest}; company projection ${d.projection_digest??"Not selected"}.`);for(const s of c.sources)para(proof,`${s.kind}: ${s.id}; digest ${s.content_digest??"Unavailable"}; version ${s.version}; effective ${s.effective_at}; first observed ${s.first_observed_at}`);for(const x of [...c.warnings,...c.assumptions])para(proof,`${x.code}: ${x.message}`);if(d.company_context)para(proof,`Company X-ray ${d.company_basis.xray_run_id}; method ${d.company_context.method} ${d.company_context.method_version}. Listing targets do not define company drift.`);
}
""".strip()
DRIFT_WIDGET_HTML = read_widget(
    title="Portfolio allocation drift",
    introduction="A bounded ranked sample with exact full-universe totals. This analysis creates no plan and performs no broker action.",
    name="portfolio-drift",
    script=_SCRIPT,
)
